using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.Json;
namespace LadderRecords;
static class ProcessAudioChecks
{
 [DllImport("winmm.dll",CharSet=CharSet.Unicode)]static extern bool PlaySound(IntPtr sound,IntPtr module,uint flags);
 public static void Tone(int frequency){const int rate=44100;using var ms=new MemoryStream();using(var writer=new BinaryWriter(ms,Encoding.ASCII,true)){writer.Write(Encoding.ASCII.GetBytes("RIFF"));writer.Write(36+rate*2);writer.Write(Encoding.ASCII.GetBytes("WAVEfmt "));writer.Write(16);writer.Write((short)1);writer.Write((short)1);writer.Write(rate);writer.Write(rate*2);writer.Write((short)2);writer.Write((short)16);writer.Write(Encoding.ASCII.GetBytes("data"));writer.Write(rate*2);for(int i=0;i<rate;i++)writer.Write((short)(Math.Sin(2*Math.PI*frequency*i/rate)*196));}var bytes=ms.ToArray();var pin=GCHandle.Alloc(bytes,GCHandleType.Pinned);try{if(!PlaySound(pin.AddrOfPinnedObject(),IntPtr.Zero,15))throw new Exception("Test sound unavailable");using var output=new StreamWriter(Console.OpenStandardOutput()){AutoFlush=true};output.WriteLine("READY");using var input=new StreamReader(Console.OpenStandardInput());input.ReadLineAsync().Wait(TimeSpan.FromSeconds(12));}finally{PlaySound(IntPtr.Zero,IntPtr.Zero,0);pin.Free();}}
 static Process StartTone(int frequency){var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardInput=true,RedirectStandardOutput=true};start.ArgumentList.Add("--test-audio-tone");start.ArgumentList.Add(frequency.ToString());var process=Process.Start(start)!;if(process.StandardOutput.ReadLineAsync().WaitAsync(TimeSpan.FromSeconds(5)).GetAwaiter().GetResult()!="READY")throw new Exception("Test tone did not start");return process;}
 static double Magnitude(float[] samples,int hz){double real=0,imaginary=0;for(int i=0;i<samples.Length;i++){real+=samples[i]*Math.Cos(2*Math.PI*hz*i/AudioIdentity.Rate);imaginary+=samples[i]*Math.Sin(2*Math.PI*hz*i/AudioIdentity.Rate);}return 2*Math.Sqrt(real*real+imaginary*imaginary)/Math.Max(1,samples.Length);}
 public static void Run(){using var target=StartTone(937);using var other=StartTone(2371);try{using var capture=new LoopbackAudio(target.Id);var watch=Stopwatch.StartNew();while(capture.Error==null&&capture.Seconds<2&&watch.Elapsed.TotalSeconds<6)Thread.Sleep(30);if(capture.Error!=null)throw new Exception(capture.Error);var samples=capture.Snapshot();double wanted=Magnitude(samples,937),unwanted=Magnitude(samples,2371);if(!capture.Initialized||samples.Length<AudioIdentity.Rate||wanted<.0001||unwanted>wanted*.15)throw new Exception($"Process isolation failed: initialized={capture.Initialized}, seconds={capture.Seconds}, wanted={wanted}, other={unwanted}");var dispose=Stopwatch.StartNew();capture.Dispose();double disposeMs=dispose.Elapsed.TotalMilliseconds;if(disposeMs>100)throw new Exception("Capture disposal blocked UI");File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"process-audio-validation.json"),JsonSerializer.Serialize(new{capture.TargetProcessId,capture.Initialized,seconds=samples.Length/(double)AudioIdentity.Rate,target_tone_amplitude=wanted,other_tone_amplitude=unwanted,other_to_target_ratio=unwanted/wanted,dispose_ms=disposeMs,isolated=true}));}finally{foreach(var process in new[]{target,other}){if(!process.HasExited){process.StandardInput.WriteLine("STOP");if(!process.WaitForExit(3000))process.Kill();}}}}
}
